  "architecture_decisions": [
    {
      "dimension": "Context Management",
      "recommendation": "Introduce a dedicated cancellable context for heartbeat operations managed by the worker lifecycle",
      "rationale": "Heartbeat RPCs currently use context.Background() which cannot be cancelled during worker shutdown. A dedicated context scoped to the worker's lifetime allows clean cancellation of in-flight heartbeats, preventing shutdown hangs.",
      "alternatives_considered": [
        "Using worker's main context (may be too broad)",
        "Creating per-heartbeat contexts (inefficient and doesn't solve cancellation on shutdown)",
        "Relying on gRPC timeouts (unreliable for graceful shutdown)"
      ],
      "files_affected": [
        "internal/internal_worker.go",
        "internal/internal_worker_heartbeat.go"
      ]
    },
    {
      "dimension": "Shutdown Order",
      "recommendation": "Cancel heartbeat context before invoking other shutdown procedures in worker.Stop()",
      "rationale": "This ensures heartbeats are cancelled and any pending RPCs can terminate gracefully before worker resources are torn down, maintaining deterministic shutdown behavior.",
      "alternatives_considered": [
        "Canceling after shutdown (may leave hanging RPCs)",
        "Canceling in parallel (risk of race conditions)",
        "No explicit ordering (unpredictable behavior)"
      ],
      "files_affected": [
        "internal/internal_worker.go"
      ]
    },
